<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { SimpleCatalogItem, SimpleCatalogService } from '@/interfaces/simpleCatalog'
const props=withDefaults(defineProps<{title:string;singular:string;description:string;icon:string;moduleLabel:string;sectionLabel:string;accent?:string;service:SimpleCatalogService;namePlaceholder?:string}>(),{accent:'#e38b2f',namePlaceholder:'Ingrese el nombre'})
const items=ref<SimpleCatalogItem[]>([]),filters=reactive({criterio:'',page:1}),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),form=reactive({nombre:'',descripcion:''})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await props.service.list(filters);items.value=r.data;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:SimpleCatalogItem){editing.value=item?.id??null;form.nombre=item?.nombre||'';form.descripcion=item?.descripcion||'';modal.value=true}
async function save(){if(!form.nombre.trim()){error.value='Ingrese el nombre del registro.';return}saving.value=true;error.value='';try{const payload={nombre:form.nombre.trim(),descripcion:form.descripcion.trim()};if(editing.value)await props.service.update(editing.value,payload);else await props.service.create(payload);modal.value=false;success.value=`${props.singular} ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?filters.page:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:SimpleCatalogItem){if(item.usage_count){error.value=`No se puede eliminar porque ${props.singular.toLowerCase()} está siendo utilizada en otros registros.`;return}if(!confirm(`¿Eliminar “${item.nombre}”?`))return;try{await props.service.remove(item.id);success.value=`${props.singular} eliminada correctamente.`;await load(filters.page)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="catalog" :style="{'--accent':accent}"><nav><RouterLink to="/inicio">Inicio</RouterLink> / {{moduleLabel}} / {{sectionLabel}} / {{title}}</nav><header class="hero"><div class="mark">{{icon}}</div><div><small>{{moduleLabel}} · {{sectionLabel}}</small><h1>{{title}}</h1><p>{{description}}</p></div><strong>{{pagination.total}} registros</strong><button @click="open()">+ Nuevo registro</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><div><small>FILTROS DE BÚSQUEDA</small><b>Buscar {{title.toLocaleLowerCase('es')}}</b></div><input v-model.trim="filters.criterio" placeholder="Nombre o descripción"><button>Buscar</button><button type="button" class="soft" @click="filters.criterio='';load(1)">Limpiar</button></form><div v-if="loading" class="empty">Cargando registros…</div><div v-else-if="!items.length" class="empty">No se encontraron registros.</div><section v-else class="cards"><article v-for="item in items" :key="item.id"><header><span>{{icon}}</span><div><small>#{{item.id}}</small><h2>{{item.nombre}}</h2></div></header><p>{{item.descripcion||'Sin descripción registrada.'}}</p><div class="meta"><span>Creado</span><b>{{item.created_at||'—'}}</b></div><footer><button class="edit" @click="open(item)">Modificar</button><button class="delete" :disabled="!!item.usage_count" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="pagination.last>1" class="pager"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">{{icon}}</div><div><small>{{sectionLabel}}</small><h2>{{editing?'Modificar':'Registrar'}} {{singular.toLowerCase()}}</h2></div><button type="button" @click="modal=false">×</button></header><label>Nombre *<input v-model="form.nombre" :placeholder="namePlaceholder" maxlength="45" required></label><label>Descripción<textarea v-model="form.descripcion" rows="3" maxlength="100"></textarea><span>{{form.descripcion.length}} / 100</span></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
