m;line-height:1.45}.meta{padding:6px;display:flex;justify-content:space-between;border-radius:5px;background:#f5f7f8;font-size:.44rem}.cards footer{margin-top:8px;display:flex;gap:5px}.cards footer button{flex:1;padding:7px;border:0;border-radius:5px;font-size:.43rem}.edit{color:#79500b;background:#ffe7bd}.delete{color:#a23d43;background:#fde8e8}.delete:disabled{opacity:.4}.pager{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:10px;font-size:.52rem}.pager button:disabled{opacity:.45}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(480px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{margin-top:10px;display:grid;gap:4px;font-size:.48rem}.dialog label span{text-align:right;color:#89959a;font-size:.42rem}.dialog footer{margin-top:14px;display:flex;justify-content:flex-end;gap:5px}@media(max-width:900px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.cards{grid-template-columns:repeat(2,1fr)}.filters>div,.filters input{width:100%}}@media(max-width:550px){.cards{grid-template-columns:1fr}}
</style>
